using Microsoft.Extensions.Logging; using Sigov.Application.Agro.Geo; using Sigov.Application.Agro.Permissions; using Sigov.Application.Common; using Sigov.Domain.Common;
namespace Sigov.Application.Agro.InfraestruturaRural;
public sealed class AgroEstradaVicinalValidator{private readonly ICoordenadaValidator _coord; private readonly IGeoJsonValidator _geo; public AgroEstradaVicinalValidator(ICoordenadaValidator coord,IGeoJsonValidator geo){_coord=coord;_geo=geo;} public Result Validar(AgroEstradaVicinalCreateRequest r){if(string.IsNullOrWhiteSpace(r.Codigo))return Result.Failure("Estrada exige código."); if(string.IsNullOrWhiteSpace(r.Nome))return Result.Failure("Estrada exige nome."); if(r.ExtensaoKm<0)return Result.Failure("Extensão em km não pode ser negativa."); var a=_coord.Validar(r.LatitudeInicio,r.LongitudeInicio); if(a.IsFailure)return a; var b=_coord.Validar(r.LatitudeFim,r.LongitudeFim); if(b.IsFailure)return b; return _geo.Validar(r.GeoJson);} public Result Validar(AgroEstradaVicinalUpdateRequest r)=>Validar(new AgroEstradaVicinalCreateRequest(r.Codigo,r.Nome,r.LocalidadeInicio,r.LocalidadeFim,r.ComunidadesAtendidasJson,r.ExtensaoKm,r.TipoRevestimento,r.Situacao,r.LatitudeInicio,r.LongitudeInicio,r.LatitudeFim,r.LongitudeFim,r.GeoJson,r.Observacao));}
public sealed class AgroPontoCriticoValidator{private readonly ICoordenadaValidator _coord; private readonly IGeoJsonValidator _geo; public AgroPontoCriticoValidator(ICoordenadaValidator coord,IGeoJsonValidator geo){_coord=coord;_geo=geo;} public Result Validar(AgroPontoCriticoCreateRequest r){if(string.IsNullOrWhiteSpace(r.TipoPonto))return Result.Failure("Ponto crítico exige tipo."); if(string.IsNullOrWhiteSpace(r.Descricao))return Result.Failure("Ponto crítico exige descrição."); if(string.IsNullOrWhiteSpace(r.Severidade))return Result.Failure("Ponto crítico exige severidade."); var c=_coord.Validar(r.Latitude,r.Longitude); return c.IsFailure?c:_geo.Validar(r.GeoJson);}}
public sealed class AgroOcorrenciaRuralValidator{public Result Validar(AgroOcorrenciaRuralCreateRequest r){if(string.IsNullOrWhiteSpace(r.Numero))return Result.Failure("Ocorrência exige número."); if(string.IsNullOrWhiteSpace(r.TipoOcorrencia))return Result.Failure("Ocorrência exige tipo."); return string.IsNullOrWhiteSpace(r.Descricao)?Result.Failure("Ocorrência exige descrição."):Result.Success();}}
public sealed class AgroManutencaoRuralValidator{public Result Validar(AgroManutencaoRuralCreateRequest r){if(string.IsNullOrWhiteSpace(r.Descricao))return Result.Failure("Manutenção exige descrição."); if(r.CustoEstimado<0||r.CustoRealizado<0)return Result.Failure("Custo não pode ser negativo."); if(string.Equals(r.Status,"EXECUTADA",StringComparison.OrdinalIgnoreCase)&&r.DataExecucao is null)return Result.Failure("Manutenção executada exige data de execução."); return Result.Success();}}
public sealed class AgroEstradaVicinalPermissionChecker{private readonly IAgroAccessChecker _access; public AgroEstradaVicinalPermissionChecker(IAgroAccessChecker access)=>_access=access; public Task<Result<AgroAccessContext>> CheckAsync(string permission,string feature,CancellationToken ct)=>_access.CheckAsync(new AgroAccessRequest(permission,feature),ct);} public sealed class AgroEstradaVicinalAuditWriter{private readonly ILogger<AgroEstradaVicinalAuditWriter> _logger; public AgroEstradaVicinalAuditWriter(ILogger<AgroEstradaVicinalAuditWriter> logger)=>_logger=logger; public Task WriteAsync(string acao,long id,CancellationToken ct){_logger.LogInformation("Auditoria Agro Parte 5 {Acao} {Id}",acao,id); return Task.CompletedTask;}}
public sealed class AgroEstradaVicinalService:IAgroEstradaVicinalService{private readonly AgroEstradaVicinalPermissionChecker _p;private readonly AgroEstradaVicinalValidator _v;private readonly AgroEstradaVicinalAuditWriter _a;private readonly IAgroInfraestruturaRuralRepository _r; public AgroEstradaVicinalService(AgroEstradaVicinalPermissionChecker p,AgroEstradaVicinalValidator v,AgroEstradaVicinalAuditWriter a,IAgroInfraestruturaRuralRepository r){_p=p;_v=v;_a=a;_r=r;} public async Task<Result<PagedResult<AgroEstradaVicinalResponse>>> ListarAsync(AgroEstradaVicinalFiltro f,CancellationToken ct){var c=await _p.CheckAsync(AgroPermissions.EstradaVisualizar,"agro.estradas_vicinais",ct); if(c.IsFailure)return Result<PagedResult<AgroEstradaVicinalResponse>>.Failure(c.Error!); if(!c.Value!.EntidadeId.HasValue)return Result<PagedResult<AgroEstradaVicinalResponse>>.Failure("Entidade obrigatória."); var page=f with{Page=Math.Max(1,f.Page),PageSize=Math.Clamp(f.PageSize,1,100)}; return Result<PagedResult<AgroEstradaVicinalResponse>>.Success(await _r.ListarEstradasAsync(c.Value.TenantId,c.Value.EntidadeId.Value,page,ct));} public async Task<Result<AgroEstradaVicinalResponse>> ObterAsync(long id,CancellationToken ct){var c=await _p.CheckAsync(AgroPermissions.EstradaVisualizar,"agro.estradas_vicinais",ct); if(c.IsFailure)return Result<AgroEstradaVicinalResponse>.Failure(c.Error!); var row=await _r.ObterEstradaAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,ct); return row is null?Result<AgroEstradaVicinalResponse>.Failure("Estrada vicinal não encontrada."):Result<AgroEstradaVicinalResponse>.Success(row);} public async Task<Result<long>> CriarAsync(AgroEstradaVicinalCreateRequest r,CancellationToken ct){var c=await _p.CheckAsync(AgroPermissions.EstradaCriar,"agro.estradas_vicinais",ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return Result<long>.Failure(v.Error!); var id=await _r.CriarEstradaAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.UsuarioId,r,ct); await _a.WriteAsync("AgroEstradaVicinalCriada",id,ct); return Result<long>.Success(id);} public async Task<Result> AtualizarAsync(long id,AgroEstradaVicinalUpdateRequest r,CancellationToken ct){var c=await _p.CheckAsync(AgroPermissions.EstradaEditar,"agro.estradas_vicinais",ct); if(c.IsFailure)return Result.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return v; await _r.AtualizarEstradaAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,c.Value.UsuarioId,r,ct); return Result.Success();} public async Task<Result> ExcluirAsync(long id,CancellationToken ct){var c=await _p.CheckAsync(AgroPermissions.EstradaExcluir,"agro.estradas_vicinais",ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.ExcluirEstradaAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,c.Value.UsuarioId,ct); return Result.Success();}}
public sealed class AgroPontoCriticoService:IAgroPontoCriticoService{private readonly IAgroAccessChecker _a;private readonly AgroPontoCriticoValidator _v;private readonly IAgroInfraestruturaRuralRepository _r; public AgroPontoCriticoService(IAgroAccessChecker a,AgroPontoCriticoValidator v,IAgroInfraestruturaRuralRepository r){_a=a;_v=v;_r=r;} async Task<Result<AgroAccessContext>> C(string p,CancellationToken ct)=>await _a.CheckAsync(new AgroAccessRequest(p,"agro.pontos_criticos"),ct); public async Task<Result<PagedResult<AgroPontoCriticoResponse>>> ListarAsync(AgroEstradaVicinalFiltro f,CancellationToken ct){var c=await C(AgroPermissions.PontoCriticoVisualizar,ct); if(c.IsFailure)return Result<PagedResult<AgroPontoCriticoResponse>>.Failure(c.Error!); return Result<PagedResult<AgroPontoCriticoResponse>>.Success(await _r.ListarPontosAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,f with{PageSize=Math.Clamp(f.PageSize,1,100)},ct));} public async Task<Result<long>> CriarAsync(long? estradaId,AgroPontoCriticoCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.PontoCriticoCriar,ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var req=r with{EstradaVicinalId=estradaId??r.EstradaVicinalId}; var v=_v.Validar(req); if(v.IsFailure)return Result<long>.Failure(v.Error!); return Result<long>.Success(await _r.CriarPontoAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.UsuarioId,req,ct));} public async Task<Result> AtualizarAsync(long id,AgroPontoCriticoCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.PontoCriticoEditar,ct); if(c.IsFailure)return Result.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return v; await _r.AtualizarPontoStatusAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,r.Status,c.Value.UsuarioId,ct); return Result.Success();} public async Task<Result> ResolverAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.PontoCriticoResolver,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.AtualizarPontoStatusAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,"RESOLVIDO",c.Value.UsuarioId,ct); return Result.Success();}}
public sealed class AgroOcorrenciaRuralService:IAgroOcorrenciaRuralService{private readonly IAgroAccessChecker _a;private readonly AgroOcorrenciaRuralValidator _v;private readonly IAgroInfraestruturaRuralRepository _r; public AgroOcorrenciaRuralService(IAgroAccessChecker a,AgroOcorrenciaRuralValidator v,IAgroInfraestruturaRuralRepository r){_a=a;_v=v;_r=r;} async Task<Result<AgroAccessContext>> C(string p,CancellationToken ct)=>await _a.CheckAsync(new AgroAccessRequest(p,"agro.ocorrencias_rurais"),ct); public async Task<Result<PagedResult<AgroOcorrenciaRuralResponse>>> ListarAsync(AgroEstradaVicinalFiltro f,CancellationToken ct){var c=await C(AgroPermissions.OcorrenciaVisualizar,ct); if(c.IsFailure)return Result<PagedResult<AgroOcorrenciaRuralResponse>>.Failure(c.Error!); return Result<PagedResult<AgroOcorrenciaRuralResponse>>.Success(await _r.ListarOcorrenciasAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.ExercicioId,f,ct));} public async Task<Result<AgroOcorrenciaRuralResponse>> ObterAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.OcorrenciaVisualizar,ct); if(c.IsFailure)return Result<AgroOcorrenciaRuralResponse>.Failure(c.Error!); var row=await _r.ObterOcorrenciaAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,ct); return row is null?Result<AgroOcorrenciaRuralResponse>.Failure("Ocorrência rural não encontrada."):Result<AgroOcorrenciaRuralResponse>.Success(row);} public async Task<Result<long>> CriarAsync(AgroOcorrenciaRuralCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.OcorrenciaCriar,ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return Result<long>.Failure(v.Error!); return Result<long>.Success(await _r.CriarOcorrenciaAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.ExercicioId,c.Value.UsuarioId,r,ct));} public async Task<Result> AtualizarAsync(long id,AgroOcorrenciaRuralCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.OcorrenciaEditar,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.AtualizarOcorrenciaStatusAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,r.Status,c.Value.UsuarioId,ct); return Result.Success();} public Task<Result> ResolverAsync(long id,CancellationToken ct)=>Status(id,"RESOLVIDA",AgroPermissions.OcorrenciaResolver,ct); public Task<Result> CancelarAsync(long id,CancellationToken ct)=>Status(id,"CANCELADA",AgroPermissions.OcorrenciaCancelar,ct); async Task<Result> Status(long id,string s,string p,CancellationToken ct){var c=await C(p,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.AtualizarOcorrenciaStatusAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,s,c.Value.UsuarioId,ct); return Result.Success();}}
public sealed class AgroManutencaoRuralService:IAgroManutencaoRuralService{private readonly IAgroAccessChecker _a;private readonly AgroManutencaoRuralValidator _v;private readonly IAgroInfraestruturaRuralRepository _r; public AgroManutencaoRuralService(IAgroAccessChecker a,AgroManutencaoRuralValidator v,IAgroInfraestruturaRuralRepository r){_a=a;_v=v;_r=r;} async Task<Result<AgroAccessContext>> C(string p,CancellationToken ct)=>await _a.CheckAsync(new AgroAccessRequest(p,"agro.ocorrencias_rurais"),ct); public async Task<Result<PagedResult<AgroManutencaoRuralResponse>>> ListarAsync(AgroEstradaVicinalFiltro f,CancellationToken ct){var c=await C(AgroPermissions.ManutencaoVisualizar,ct); if(c.IsFailure)return Result<PagedResult<AgroManutencaoRuralResponse>>.Failure(c.Error!); return Result<PagedResult<AgroManutencaoRuralResponse>>.Success(await _r.ListarManutencoesAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.ExercicioId,f,ct));} public async Task<Result<long>> CriarAsync(AgroManutencaoRuralCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.ManutencaoCriar,ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return Result<long>.Failure(v.Error!); return Result<long>.Success(await _r.CriarManutencaoAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.ExercicioId,c.Value.UsuarioId,r,ct));} public async Task<Result> ExecutarAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.ManutencaoExecutar,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.AtualizarManutencaoStatusAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,"EXECUTADA",DateOnly.FromDateTime(DateTime.UtcNow),c.Value.UsuarioId,ct); return Result.Success();} public async Task<Result> CancelarAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.ManutencaoCancelar,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.AtualizarManutencaoStatusAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,"CANCELADA",null,c.Value.UsuarioId,ct); return Result.Success();}}
